```rust
use lasso::Spur;
use rue_rir::RirParamMode;
use crate::types::Type;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ParamRange {
    pub start: u32,
    pub len: u32,
}

impl ParamRange {
    pub fn empty() -> Self {
        Self { start: 0, len: 0 }
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }
}

#[derive(Debug, Default)]
pub struct ParamArena {
    names: Vec<Spur>,
    types: Vec<Type>,
    modes: Vec<RirParamMode>,
}

impl ParamArena {
    pub fn new() -> Self {
        Self::default()
    }

    /// Allocate function parameters (types and modes).
    pub fn alloc_func_params(
        &mut self,
        types: &[Type],
        modes: &[RirParamMode],
    ) -> ParamRange {
        debug_assert_eq!(types.len(), modes.len());
        let start = self.types.len() as u32;
        let len = types.len() as u32;
        self.types.extend_from_slice(types);
        self.modes.extend_from_slice(modes);
        // Pad names to keep indices aligned
        self.names.extend(std::iter::repeat(Spur::default()).take(types.len()));
        ParamRange { start, len }
    }

    /// Allocate method parameters (names, types).
    pub fn alloc_method_params(
        &mut self,
        names: &[Spur],
        types: &[Type],
    ) -> ParamRange {
        debug_assert_eq!(names.len(), types.len());
        let start = self.types.len() as u32;
        let len = types.len() as u32;
        self.names.extend_from_slice(names);
        self.types.extend_from_slice(types);
        // Pad modes with default
        self.modes.extend(std::iter::repeat(RirParamMode::In).take(types.len()));
        ParamRange { start, len }
    }

    pub fn get_types(&self, range: ParamRange) -> &[Type] {
        &self.types[range.start as usize..(range.start + range.len) as usize]
    }

    pub fn get_modes(&self, range: ParamRange) -> &[RirParamMode] {
        &self.modes[range.start as usize..(range.start + range.len) as usize]
    }

    pub fn get_names(&self, range: ParamRange) -> &[Spur] {
        &self.names[range.start as usize..(range.start + range.len) as usize]
    }
}
```

