## Proposed Change

Add function span tracking:

```rust
pub struct Rir {
    instructions: Vec<Inst>,
    extra: Vec<u32>,
    // NEW: Function boundaries
    function_spans: Vec<FunctionSpan>,
}

pub struct FunctionSpan {
    pub name: Symbol,
    pub start: InstRef,  // First instruction of function
    pub end: InstRef,    // One past last instruction (exclusive)
}

impl Rir {
    /// Get a view of just one function's instructions
    pub fn function_view(&self, fn_span: &FunctionSpan) -> RirFunctionView<'_> {
        RirFunctionView {
            rir: self,
            start: fn_span.start,
            end: fn_span.end,
        }
    }

    /// Iterate over function spans
    pub fn functions(&self) -> impl Iterator<Item = &FunctionSpan> {
        self.function_spans.iter()
    }
}
```

