```rust
#[test]
fn test_rex_both_extended() {
    // mov r15, r8 -> 4D 89 C7
    // REX = 0x4D = 0100 1101 (W=1, R=1, X=0, B=1)
    let code = emit_single(X86Inst::MovRR {
        dst: Operand::Physical(Reg::R15),
        src: Operand::Physical(Reg::R8),
