    // Read-only after collection phase
    rir: &'a Rir,
    struct_defs: Vec<StructDef>,
    enum_defs: Vec<EnumDef>,
    functions: HashMap<Symbol, FunctionInfo>,
    methods: HashMap<(Symbol, Symbol), MethodInfo>,

    // Mutable during analysis - blocks parallelism\!
