#[derive(Arbitrary)]
enum FuzzableX86Inst {
    MovRI32 { dst_reg: u8, imm: i32 },
    MovRI64 { dst_reg: u8, imm: i64 },
    MovRR { dst_reg: u8, src_reg: u8 },
