                dst: Operand::Physical(reg_from_index(dst_reg % 16)),
                imm,
            },
            // ...
        }
    }
}

fn reg_from_index(idx: u8) -> Reg {
    match idx {
        0 => Reg::Rax, 1 => Reg::Rcx, 2 => Reg::Rdx, /* ... */
        _ => Reg::Rax,
    }
}
